style.css:
@-moz-document url-prefix("https://www.roblox.com") {
/* Hintergrund in Rosa mit Hello Kitty Emojis */
  body {
    background-color: #ffe6f0 !important;
    background-image: url("https://i.pinimg.com/originals/6e/9c/3e/6e9c3e4c7c8e6e8f3e8e8e8e8e8e8e8e.jpg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    color: #ff69b4 !important;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
  }

  /* Buttons und Navigation rosa einfärben */
  .navbar, .btn-primary, .btn-secondary, .header, .footer {
    background-color: #ffb6c1 !important;
    border-color: #ff69b4 !important;
    color: white !important;
  }

  /* Robux-Anzeige hinzufügen */
  #header .header-content::after {
    content: "? 376,000 Robux ?";
    font-size: 18px;
    color: #ff1493;
    margin-left: 20px;
    font-weight: bold;
  }

  /* Hover-Effekte für Buttons */
  .btn-primary:hover, .btn-secondary:hover {
    background-color: #ff69b4 !important;
    color: white !important;
  }
}
